package app.yomikai.shell

import android.annotation.SuppressLint
import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.view.Gravity
import android.view.View
import android.view.inputmethod.EditorInfo
import android.webkit.WebSettings
import android.webkit.WebView
import android.widget.Button
import android.widget.EditText
import android.widget.FrameLayout
import android.widget.HorizontalScrollView
import android.widget.LinearLayout
import android.widget.Toast
import androidx.activity.ComponentActivity
import androidx.activity.OnBackPressedCallback
import androidx.activity.result.contract.ActivityResultContracts
import app.yomikai.shell.archive.openZip
import app.yomikai.shell.bridge.OnlineModels
import app.yomikai.shell.bridge.ShellBridge
import app.yomikai.shell.net.LocalServer
import app.yomikai.shell.storage.DeviceLibrary
import org.json.JSONArray
import org.json.JSONObject
import java.io.ByteArrayInputStream
import java.io.InputStream
import java.net.URLEncoder

/**
 * Оболочка: нативный таб-бар и один WebView.
 *
 * Таб-бар остаётся нативным намеренно — он должен открываться мгновенно и не
 * зависеть ни от сети, ни от веб-слоя. Вкладка «Браузер» тоже нативная: это
 * системный WebView плюс адресная строка. Всё остальное — веб-интерфейс,
 * который грузится с локального сервера оболочки.
 */
class MainActivity : ComponentActivity(), LocalServer.Routes {

    private lateinit var webView: WebView
    private lateinit var server: LocalServer
    private lateinit var library: DeviceLibrary
    private lateinit var bridge: ShellBridge
    private lateinit var tabBar: LinearLayout
    private lateinit var browserBar: LinearLayout
    private lateinit var address: EditText
    private lateinit var content: FrameLayout

    private val online by lazy { OnlineModels(this) }
    private var currentTab = TAB_LIBRARY

    /** Ассеты веб-интерфейса: маленькие, поэтому держим в памяти целиком. */
    private val assetCache = HashMap<String, ByteArray>()

    private val pickTree = registerForActivityResult(ActivityResultContracts.OpenDocumentTree()) { uri ->
        if (uri == null) return@registerForActivityResult
        val flags = Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION
        runCatching { contentResolver.takePersistableUriPermission(uri, flags) }
        val name = uri.lastPathSegment?.substringAfterLast(':')?.takeIf { it.isNotBlank() } ?: "Корень"
        library.addRoot(uri.toString(), name)
        tellWeb("'library:roots-changed'")
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        library = DeviceLibrary(this)
        setContentView(buildLayout())
        server = LocalServer(this, this)
        server.start()
        bridge = ShellBridge(
            activity = this,
            serverUrlProvider = { server.baseUrl },
            pickTree = pickTree,
            online = online,
        )
        setupWebView()
        installBackHandler()
        openTab(TAB_LIBRARY)
    }

    // --- интерфейс ----------------------------------------------------------

    private fun buildLayout(): View {
        val root = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setBackgroundColor(BACKGROUND)
        }
        content = FrameLayout(this)
        root.addView(
            content,
            LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, 0).apply { weight = 1f },
        )
        browserBar = buildBrowserBar()
        root.addView(
            browserBar,
            LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT),
        )
        tabBar = buildTabBar()
        root.addView(
            HorizontalScrollView(this).apply { addView(tabBar) },
            LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT),
        )
        return root
    }

    private fun buildTabBar(): LinearLayout = LinearLayout(this).apply {
        orientation = LinearLayout.HORIZONTAL
        gravity = Gravity.CENTER
        setPadding(0, 6, 0, 14)
        TABS.forEach { tab ->
            addView(
                Button(this@MainActivity).apply {
                    text = getString(tab.title)
                    textSize = 11f
                    isAllCaps = false
                    setPadding(8, 0, 8, 0)
                    setBackgroundColor(0x00000000)
                    setOnClickListener { openTab(tab.id) }
                    tag = tab.id
                },
                LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT).apply { weight = 1f },
            )
        }
    }

    private fun buildBrowserBar(): LinearLayout = LinearLayout(this).apply {
        orientation = LinearLayout.HORIZONTAL
        visibility = View.GONE
        setPadding(12, 10, 12, 0)
        address = EditText(this@MainActivity).apply {
            hint = getString(R.string.browser_hint)
            setSingleLine(true)
            setTextColor(0xFFE8E8EE.toInt())
            setHintTextColor(0xFF6A6A76.toInt())
            imeOptions = EditorInfo.IME_ACTION_GO
            setOnEditorActionListener { _, actionId, _ ->
                if (actionId == EditorInfo.IME_ACTION_GO) {
                    loadAddress(text.toString())
                    true
                } else {
                    false
                }
            }
        }
        addView(address, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT).apply { weight = 1f })
        addView(
            Button(this@MainActivity).apply {
                text = getString(R.string.browser_go)
                textSize = 12f
                isAllCaps = false
                setOnClickListener { loadAddress(address.text.toString()) }
            },
            LinearLayout.LayoutParams(LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT),
        )
    }

    // --- вкладки ------------------------------------------------------------

    private fun openTab(id: String) {
        currentTab = id
        browserBar.visibility = if (id == TAB_BROWSER) View.VISIBLE else View.GONE
        for (i in 0 until tabBar.childCount) {
            val button = tabBar.getChildAt(i) as? Button ?: continue
            button.setTextColor(if (button.tag == id) ACCENT else MUTED)
        }
        if (id == TAB_BROWSER) {
            val last = runCatching {
                JSONObject(bridge.getPrefs("browser")).optString("browser.last")
            }.getOrNull()
            loadAddress(last?.takeIf { it.isNotBlank() } ?: START_PAGE)
        } else {
            webView.loadUrl("${server.baseUrl}/ui/index.html?k=${server.accessToken}&tab=$id")
        }
    }

    private fun loadAddress(raw: String) {
        val value = raw.trim()
        if (value.isEmpty()) return
        val url = when {
            value.startsWith("http://") || value.startsWith("https://") -> value
            value.contains('.') && !value.contains(' ') -> "https://$value"
            else -> "https://duckduckgo.com/?q=${URLEncoder.encode(value, "UTF-8")}"
        }
        bridge.setPref("browser.last", url)
        webView.loadUrl(url)
    }

    // --- webview ------------------------------------------------------------

    @SuppressLint("SetJavaScriptEnabled")
    private fun setupWebView() {
        webView = WebView(this)
        content.addView(
            webView,
            FrameLayout.LayoutParams(
                FrameLayout.LayoutParams.MATCH_PARENT,
                FrameLayout.LayoutParams.MATCH_PARENT,
            ),
        )
        webView.settings.apply {
            javaScriptEnabled = true
            domStorageEnabled = true
            // В мост попадает только перечисленный интерфейс, но file:// и
            // content:// из страницы закрыты полностью: иначе открытая
            // страница манги тянет файлы с телефона.
            allowFileAccess = false
            allowContentAccess = false
            @Suppress("DEPRECATION")
            allowFileAccessFromFileURLs = false
            @Suppress("DEPRECATION")
            allowUniversalAccessFromFileURLs = false
            mixedContentMode = WebSettings.MIXED_CONTENT_NEVER_ALLOW
            cacheMode = WebSettings.LOAD_NO_CACHE
            setGeolocationEnabled(false)
            mediaPlaybackRequiresUserGesture = true
            javaScriptCanOpenWindowsAutomatically = false
            setSupportMultipleWindows(false)
        }
        webView.addJavascriptInterface(bridge, "Yomi")
    }

    private fun installBackHandler() {
        onBackPressedDispatcher.addCallback(
            this,
            object : OnBackPressedCallback(true) {
                override fun handleOnBackPressed() {
                    when {
                        currentTab == TAB_BROWSER && webView.canGoBack() -> webView.goBack()
                        currentTab != TAB_LIBRARY -> openTab(TAB_LIBRARY)
                        else -> {
                            isEnabled = false
                            onBackPressedDispatcher.onBackPressed()
                        }
                    }
                }
            },
        )
    }

    // --- сервер: ассеты -----------------------------------------------------

    override fun asset(path: String): Pair<InputStream, Long>? {
        val name = path.removePrefix("/").ifEmpty { "index.html" }
        val bytes = assetCache.getOrPut(name) {
            runCatching { assets.open("web/$name").use { it.readBytes() } }.getOrNull() ?: return null
        }
        return ByteArrayInputStream(bytes) to bytes.size.toLong()
    }

    // --- сервер: устройство -------------------------------------------------

    override fun device(uri: String, rangeStart: Long, rangeLength: Long): LocalServer.DeviceStream? =
        runCatching {
            val bytes = library.readBytes(uri) ?: return null
            streamSlice(bytes, rangeStart, mimeOf(uri))
        }.getOrNull()

    override fun archiveEntries(uri: String): String? = runCatching {
        val (channel, size) = library.openChannel(uri) ?: return null
        openZip(channel, size).use { zip ->
            JSONArray().apply {
                zip.imageEntries(DeviceLibrary.IMAGE_EXTENSIONS).forEach { entry ->
                    put(JSONObject().put("name", entry.name).put("size", entry.compressedSize))
                }
            }.toString()
        }
    }.getOrNull()

    override fun archiveEntry(
        uri: String,
        entry: String,
        rangeStart: Long,
        rangeLength: Long,
    ): LocalServer.DeviceStream? = runCatching {
        val (channel, size) = library.openChannel(uri) ?: return null
        openZip(channel, size).use { zip ->
            val found = zip.find(entry) ?: return null
            streamSlice(zip.read(found), rangeStart, mimeOf(entry))
        }
    }.getOrNull()

    /**
     * Chromium шлёт Range на каждую картинку, поэтому Range поддержан честно.
     * Файл целиком в памяти: это страница comics-архива, то есть картинка на
     * сотни килобайт — держать её целику дешевле, чем городить потоковое чтение
     * со смещением.
     */
    private fun streamSlice(bytes: ByteArray, from: Long, mime: String): LocalServer.DeviceStream {
        val start = from.coerceIn(0, bytes.size.toLong()).toInt()
        val slice = if (start == 0) bytes else bytes.copyOfRange(start, bytes.size)
        return LocalServer.DeviceStream(ByteArrayInputStream(slice), slice.size.toLong(), mime)
    }

    override fun rootsJson(): String = JSONArray().apply {
        library.roots().forEach { put(JSONObject().put("uri", it).put("name", library.rootName(it))) }
    }.toString()

    override fun listJson(uri: String?): String {
        val target = uri ?: library.roots().firstOrNull()
            ?: return JSONArray().toString()
        return JSONArray().apply {
            library.list(target).forEach { node ->
                put(
                    JSONObject()
                        .put("uri", node.uri)
                        .put("name", node.name)
                        .put("dir", node.isDirectory)
                        .put("size", node.size)
                        .put("ext", DeviceLibrary.extensionOf(node.name)),
                )
            }
        }.toString()
    }

    // --- жизненный цикл -----------------------------------------------------

    override fun onPause() {
        webView.onPause()
        super.onPause()
    }

    override fun onResume() {
        super.onResume()
        webView.onResume()
    }

    override fun onDestroy() {
        server.stop()
        webView.destroy()
        super.onDestroy()
    }

    private fun tellWeb(event: String) {
        webView.post {
            runCatching { webView.evaluateJavascript("window.YomiShell && YomiShell.event($event)", null) }
        }
    }

    private fun mimeOf(name: String): String = when (name.substringAfterLast('.', "").lowercase()) {
        "jpg", "jpeg" -> "image/jpeg"
        "png" -> "image/png"
        "webp" -> "image/webp"
        "gif" -> "image/gif"
        "avif" -> "image/avif"
        "pdf" -> "application/pdf"
        "txt", "md" -> "text/plain; charset=utf-8"
        else -> "application/octet-stream"
    }

    private data class TabDef(val id: String, val title: Int)

    private companion object {
        const val TAB_LIBRARY = "library"
        const val TAB_BROWSER = "browser"
        const val START_PAGE = "https://duckduckgo.com"
        val BACKGROUND = 0xFF0B0B0F.toInt()
        val ACCENT = 0xFF7C4DFF.toInt()
        val MUTED = 0xFF8A8A96.toInt()
        val TABS = listOf(
            TabDef(TAB_LIBRARY, R.string.tab_library),
            TabDef("reader", R.string.tab_reader),
            TabDef("chat", R.string.tab_chat),
            TabDef("settings", R.string.tab_settings),
            TabDef(TAB_BROWSER, R.string.tab_browser),
        )
    }
}

package app.yomikai.shell.net

import android.content.Context
import java.io.BufferedOutputStream
import java.io.IOException
import java.io.InputStream
import java.net.InetAddress
import java.net.ServerSocket
import java.net.Socket
import java.net.URLDecoder
import java.util.concurrent.Executors
import java.util.concurrent.atomic.AtomicBoolean

/**
 * Локальный сервер оболочки: единый origin для веб-интерфейса и для данных.
 *
 * Почему сервер, а не `file://` и не мост с base64:
 *  • `file://` не даёт нормального origin — страница не получает ни
 *    хранилища, ни честных относительных URL, и это же блокирует часть API;
 *  • мост `@JavascriptInterface` с base64 раздувает картинку страницы
 *    примерно вчетверо и держит её строкой в памяти JS; на 200-страничном
 *    тайтле это сотни мегабайт и постоянное копирование;
 *  • сервер отдаёт поток, поэтому `<img src=…>` работает так же, как с
 *    интернетом, и картинка декодируется на устройстве силами Chromium.
 *
 * Слушает только 127.0.0.1 и только с токеном в адресе: из локальной сети
 * сервер недоступен, а без токена — недоступен и с телефона.
 */
class LocalServer(
    private val context: Context,
    private val routes: Routes,
) {
    interface Routes {
        /** Отдать файл из assets (веб-интерфейс). */
        fun asset(path: String): Pair<InputStream, Long>?

        /** Отдать поток с устройства по URI. */
        fun device(uri: String, rangeStart: Long, rangeLength: Long): DeviceStream?

        /** Корни библиотеки как JSON. */
        fun rootsJson(): String

        /** Содержимое папки как JSON. */
        fun listJson(uri: String?): String

        /** Список ZIP-записей архива как JSON. */
        fun archiveEntries(uri: String): String?

        /** Байт из архива. */
        fun archiveEntry(uri: String, entry: String, rangeStart: Long, rangeLength: Long): DeviceStream?
    }

    data class DeviceStream(val stream: InputStream, val length: Long, val mime: String)

    private val token = java.util.UUID.randomUUID().toString().replace("-", "")

    /**
     * Ключ доступа к серверу. Отдаётся веб-странице один раз при загрузке:
     * без него данные с телефона не читаются даже с самого устройства.
     */
    val accessToken: String get() = token

    private val running = AtomicBoolean(false)
    private var socket: ServerSocket? = null

    /** Порт известен только после старта; веб-страница получает его через мост. */
    @Volatile
    var port: Int = 0
        private set

    @Volatile
    var baseUrl: String = ""
        private set

    fun start() {
        if (!running.compareAndSet(false, true)) return
        val server = ServerSocket(0, 8, InetAddress.getByName("127.0.0.1"))
        socket = server
        port = server.localPort
        baseUrl = "http://127.0.0.1:$port"
        val pool = Executors.newFixedThreadPool(6)
        Thread({ acceptLoop(server, pool) }, "shell-accept").apply { isDaemon = true }.start()
    }

    fun stop() {
        running.set(false)
        runCatching { socket?.close() }
        socket = null
    }

    private fun acceptLoop(server: ServerSocket, pool: java.util.concurrent.ExecutorService) {
        while (running.get() && !server.isClosed) {
            val client = try {
                server.accept()
            } catch (e: IOException) {
                if (running.get()) continue else break
            }
            pool.execute {
                runCatching { handle(client) }
                    .onFailure { runCatching { client.close() } }
            }
        }
    }

    private fun handle(client: Socket) {
        client.use { socket ->
            socket.soTimeout = 30_000
            val input = socket.getInputStream()
            val requestLine = readLine(input) ?: return
            val parts = requestLine.split(' ')
            if (parts.size < 2) return
            val method = parts[0]
            val rawTarget = parts[1]
            // Заголовки читаем до пустой строки: без Content-Length мы их не
            // используем, но пропустить обязаны, иначе попадём в тело запроса.
            while (true) {
                val line = readLine(input) ?: break
                if (line.isEmpty()) break
            }

            val target = URLDecoder.decode(rawTarget.substringBefore('?'), "UTF-8")
            val query = parseQuery(rawTarget.substringAfter('?', ""))
            if (query["k"] != token && !target.startsWith("/ui/")) {
                writeSimple(socket.getOutputStream(), 403, "text/plain; charset=utf-8", "нет ключа")
                return
            }
            when {
                target == "/" -> redirect(socket.getOutputStream(), "/ui/index.html?k=$token")
                target.startsWith("/ui/") -> serveAsset(socket, target.removePrefix("/ui/"), method)
                target == "/api/roots" -> json(socket.getOutputStream(), routes.rootsJson())
                target == "/api/list" -> json(socket.getOutputStream(), routes.listJson(query["uri"]))
                target == "/api/file" -> serveDevice(socket, query, method)
                target == "/api/zip/list" -> json(socket.getOutputStream(), routes.archiveEntries(query["uri"].orEmpty()) ?: "[]")
                target == "/api/zip/entry" -> serveArchiveEntry(socket, query, method)
                else -> writeSimple(socket.getOutputStream(), 404, "text/plain; charset=utf-8", "нет такого")
            }
        }
    }

    private fun serveAsset(socket: Socket, path: String, method: String) {
        val (stream, length) = routes.asset(path.ifEmpty { "index.html" })
            ?: return writeSimple(socket.getOutputStream(), 404, "text/plain; charset=utf-8", "нет ассета")
        stream.use {
            val mime = when {
                path.endsWith(".html") -> "text/html; charset=utf-8"
                path.endsWith(".js") -> "text/javascript; charset=utf-8"
                path.endsWith(".css") -> "text/css; charset=utf-8"
                path.endsWith(".svg") -> "image/svg+xml"
                path.endsWith(".png") -> "image/png"
                path.endsWith(".webp") -> "image/webp"
                path.endsWith(".json") -> "application/json; charset=utf-8"
                else -> "application/octet-stream"
            }
            val out = socket.getOutputStream()
            out.write(
                ("HTTP/1.1 200 OK\r\nContent-Type: $mime\r\nContent-Length: $length\r\n" +
                    "Cache-Control: no-store\r\nConnection: close\r\n\r\n").toByteArray(),
            )
            if (method != "HEAD") copy(it, BufferedOutputStream(out))
        }
    }

    private fun serveDevice(socket: Socket, query: Map<String, String>, method: String) {
        val uri = query["uri"] ?: return writeSimple(socket.getOutputStream(), 400, "text/plain", "нет uri")
        val range = parseRange(query)
        val data = routes.device(uri, range.first, range.second)
            ?: return writeSimple(socket.getOutputStream(), 404, "text/plain; charset=utf-8", "файл не открылся")
        data.stream.use {
            val out = socket.getOutputStream()
            val status = if (range.first > 0) "206 Partial Content" else "200 OK"
            val headers = buildString {
                append("HTTP/1.1 $status\r\n")
                append("Content-Type: ${data.mime}\r\n")
                append("Content-Length: ${data.length}\r\n")
                if (range.first > 0) {
                    append("Content-Range: bytes ${range.first}-${range.first + data.length - 1}/*\r\n")
                }
                append("Accept-Ranges: bytes\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n")
            }
            out.write(headers.toByteArray())
            if (method != "HEAD") copy(it, BufferedOutputStream(out))
        }
    }

    private fun serveArchiveEntry(socket: Socket, query: Map<String, String>, method: String) {
        val uri = query["uri"] ?: return writeSimple(socket.getOutputStream(), 400, "text/plain", "нет uri")
        val entry = query["e"] ?: return writeSimple(socket.getOutputStream(), 400, "text/plain", "нет записи")
        val range = parseRange(query)
        val data = routes.archiveEntry(uri, entry, range.first, range.second)
            ?: return writeSimple(socket.getOutputStream(), 404, "text/plain; charset=utf-8", "запись не читается")
        data.stream.use {
            val out = socket.getOutputStream()
            out.write(
                ("HTTP/1.1 200 OK\r\nContent-Type: ${data.mime}\r\nContent-Length: ${data.length}\r\n" +
                    "Cache-Control: no-store\r\nConnection: close\r\n\r\n").toByteArray(),
            )
            if (method != "HEAD") copy(it, BufferedOutputStream(out))
        }
    }

    private fun copy(input: InputStream, out: BufferedOutputStream) {
        val buffer = ByteArray(128 * 1024)
        while (true) {
            val n = input.read(buffer)
            if (n < 0) break
            out.write(buffer, 0, n)
        }
        out.flush()
    }

    private fun redirect(out: java.io.OutputStream, location: String) {
        out.write(
            ("HTTP/1.1 302 Found\r\nLocation: $location\r\nContent-Length: 0\r\nConnection: close\r\n\r\n")
                .toByteArray(),
        )
        out.flush()
    }

    private fun json(out: java.io.OutputStream, body: String) {
        val bytes = body.toByteArray()
        out.write(
            ("HTTP/1.1 200 OK\r\nContent-Type: application/json; charset=utf-8\r\n" +
                "Content-Length: ${bytes.size}\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n")
                .toByteArray(),
        )
        out.write(bytes)
        out.flush()
    }

    private fun writeSimple(out: java.io.OutputStream, code: Int, mime: String, body: String) {
        val bytes = body.toByteArray()
        out.write(
            ("HTTP/1.1 $code X\r\nContent-Type: $mime\r\nContent-Length: ${bytes.size}\r\n" +
                "Connection: close\r\n\r\n").toByteArray(),
        )
        out.write(bytes)
        out.flush()
    }

    private fun parseRange(query: Map<String, String>): Pair<Long, Long> {
        val start = query["from"]?.toLongOrNull() ?: 0L
        val length = query["len"]?.toLongOrNull() ?: -1L
        return start to length
    }

    private fun readLine(input: InputStream): String? {
        val builder = StringBuilder()
        while (true) {
            val c = input.read()
            if (c < 0) return if (builder.isEmpty()) null else builder.toString()
            if (c == '\n'.code) return builder.toString().removeSuffix("\r")
            builder.append(c.toChar())
            if (builder.length > 8192) return null
        }
    }

    private fun parseQuery(raw: String): Map<String, String> {
        if (raw.isEmpty()) return emptyMap()
        return raw.split('&').mapNotNull { part ->
            val idx = part.indexOf('=')
            if (idx <= 0) null else {
                URLDecoder.decode(part.substring(0, idx), "UTF-8") to
                    URLDecoder.decode(part.substring(idx + 1), "UTF-8")
            }
        }.toMap()
    }
}

package app.yomikai.shell.storage

import android.content.ContentResolver
import android.content.Context
import android.content.Intent
import android.net.Uri
import android.provider.DocumentsContract
import java.io.FileInputStream
import java.nio.channels.FileChannel

/** Запись каталога, как её видит веб-слой. */
data class Node(
    val uri: String,
    val name: String,
    val isDirectory: Boolean,
    val size: Long,
    val children: Int,
)

/**
 * Ленивая библиотека: список папок и файлов прямо с устройства.
 *
 * Ни базы, ни кэша, ни разбора ComicInfo — только то, что отдаёт SAF. Каталог
 * читается при каждом запросе, поэтому список всегда актуален: файл, добавленный
 * в папку, появляется сразу и без нажатия «обновить».
 *
 * Архивы не распаковываются: каталог читается по центральному каталогу ZIP
 * через [openZipChannel], то есть страница отдаётся потоком с устройства.
 */
class DeviceLibrary(private val context: Context) {

    private val prefs = context.getSharedPreferences("roots", Context.MODE_PRIVATE)

    fun roots(): List<String> = prefs.getStringSet("uris", emptySet()).orEmpty().toList()

    fun addRoot(uri: String, name: String) {
        val next = roots().toMutableList()
        if (uri !in next) next.add(uri)
        prefs.edit()
            .putStringSet("uris", next.toSet())
            .putString("name:$uri", name)
            .apply()
    }

    fun removeRoot(uri: String) {
        runCatching {
            context.contentResolver.releasePersistableUriPermission(
                Uri.parse(uri),
                Intent.FLAG_GRANT_READ_URI_PERMISSION,
            )
        }
        prefs.edit()
            .putStringSet("uris", roots().filter { it != uri }.toSet())
            .remove("name:$uri")
            .apply()
    }

    fun rootName(uri: String): String = prefs.getString("name:$uri", null) ?: "Корень"

    fun list(uri: String): List<Node> {
        val parsed = Uri.parse(uri)
        val resolver = context.contentResolver
        val children = if (isTreeUri(parsed)) {
            DocumentsContract.buildChildDocumentsUriUsingTree(
                parsed,
                DocumentsContract.getTreeDocumentId(parsed),
            )
        } else {
            parsed
        }
        val out = mutableListOf<Node>()
        resolver.query(children, null, null, null, null)?.use { cursor ->
            val uriCol = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_DOCUMENT_ID)
            val nameCol = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_DISPLAY_NAME)
            val sizeCol = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_SIZE)
            val mimeCol = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_MIME_TYPE)
            while (cursor.moveToNext()) {
                val docId = if (uriCol >= 0) cursor.getString(uriCol) else null
                val name = if (nameCol >= 0) cursor.getString(nameCol) else null
                val size = if (sizeCol >= 0 && !cursor.isNull(sizeCol)) cursor.getLong(sizeCol) else 0L
                val mime = if (mimeCol >= 0) cursor.getString(mimeCol) else null
                val childUri = if (isTreeUri(parsed)) {
                    DocumentsContract.buildDocumentUriUsingTree(parsed, docId.orEmpty())
                } else {
                    parsed
                }
                out.add(
                    Node(
                        uri = childUri.toString(),
                        name = name.orEmpty(),
                        isDirectory = mime == DocumentsContract.Document.MIME_TYPE_DIR,
                        size = size,
                        children = 0,
                    ),
                )
            }
        }
        return out
    }

    /**
     * Открыть поток с возможностью seek. Для ZIP это обязательно: чтение записи
     * идёт по смещению из локального заголовка.
     */
    fun openChannel(uri: String): Pair<FileChannel, Long>? = runCatching {
        val pfd = context.contentResolver.openFileDescriptor(Uri.parse(uri), "r") ?: return null
        val stream = FileInputStream(pfd.fileDescriptor)
        val channel = stream.channel
        val size = if (channel.size() > 0) channel.size() else pfd.statSize
        // Канал держит дескриптор открытым: закрывать pfd отдельно нельзя.
        channel to size
    }.getOrNull()

    fun readBytes(uri: String, maxBytes: Long = 32L * 1024 * 1024): ByteArray? = runCatching {
        context.contentResolver.openInputStream(Uri.parse(uri))?.use { input ->
            val out = java.io.ByteArrayOutputStream()
            val buffer = ByteArray(128 * 1024)
            var total = 0L
            while (true) {
                val n = input.read(buffer)
                if (n < 0) break
                total += n
                if (total > maxBytes) throw java.io.IOException("Файл больше лимита $maxBytes")
                out.write(buffer, 0, n)
            }
            out.toByteArray()
        }
    }.getOrNull()

    fun isTreeUri(uri: Uri): Boolean =
        android.provider.DocumentsContract.isTreeUri(uri)

    companion object {
        val IMAGE_EXTENSIONS = setOf("jpg", "jpeg", "png", "webp", "gif", "avif", "jxl")
        val ARCHIVE_EXTENSIONS = setOf("zip", "cbz", "cbr", "cb7", "7z", "rar", "tar")
        val BOOK_EXTENSIONS = setOf("pdf", "epub", "fb2", "docx", "txt", "md", "html")

        fun extensionOf(name: String): String = name.substringAfterLast('.', "").lowercase()
    }
}

package app.yomikai.shell.bridge

import android.app.Activity
import android.content.Context
import android.content.Intent
import android.net.Uri
import android.provider.Settings
import android.webkit.JavascriptInterface
import android.widget.Toast
import androidx.activity.result.ActivityResultLauncher
import org.json.JSONArray
import org.json.JSONObject
import java.io.ByteArrayOutputStream

/**
 * Мост между веб-интерфейсом и тем, что веб сделать не может.
 *
 * Три вещи принципиально остаются нативными:
 *  1. доступ к папкам на устройстве — в браузере это `showDirectoryPicker()`,
 *     доступен только в Chromium и только по жесту пользователя;
 *  2. сетевые вызовы к моделям — Zen, OpenRouter и Lens не отдают CORS-заголовки,
 *     поэтому из страницы они невозможны в принципе;
 *  3. ключи провайдеров — они лежат в приватных настройках приложения и в веб
 *     не отдаются, ровно как и не читаются.
 */
class ShellBridge(
    private val activity: Activity,
    private val serverUrlProvider: () -> String,
    private val pickTree: ActivityResultLauncher<Uri?>,
    private val online: OnlineModels,
) {
    private val prefs get() = activity.getSharedPreferences("shell", Context.MODE_PRIVATE)

    // --- окружение -----------------------------------------------------------

    @JavascriptInterface
    fun baseUrl(): String = serverUrlProvider()

    @JavascriptInterface
    fun appVersion(): String =
        runCatching { activity.packageManager.getPackageInfo(activity.packageName, 0).versionName }
            .getOrNull() ?: "?"

    // --- настройки -----------------------------------------------------------

    @JavascriptInterface
    fun getPrefs(prefix: String): String {
        val out = JSONObject()
        prefs.all.forEach { (key, value) ->
            if (prefix.isEmpty() || key.startsWith("$prefix.")) out.put(key, value)
        }
        return out.toString()
    }

    @JavascriptInterface
    fun setPref(key: String, value: String) {
        val editor = prefs.edit()
        // Всё, что не помечено префиксом, — внутреннее состояние оболочки.
        editor.putString(key, value)
        editor.apply()
    }

    @JavascriptInterface
    fun removePref(key: String) {
        prefs.edit().remove(key).apply()
    }

    // --- устройство ----------------------------------------------------------

    /** Открыть системный выбор папки. Результат приходит в pickTree. */
    @JavascriptInterface
    fun pickLibraryFolder() {
        activity.runOnUiThread { pickTree.launch(null) }
    }

    @JavascriptInterface
    fun toast(message: String) {
        activity.runOnUiThread {
            Toast.makeText(activity, message, Toast.LENGTH_SHORT).show()
        }
    }

    @JavascriptInterface
    fun openExternal(url: String) {
        val uri = runCatching { Uri.parse(url) }.getOrNull() ?: return
        if (uri.scheme != "http" && uri.scheme != "https" && uri.scheme != "yomikai") return
        activity.runOnUiThread {
            runCatching {
                activity.startActivity(Intent(Intent.ACTION_VIEW, uri).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))
            }.onFailure {
                Toast.makeText(activity, "Нечем открыть ссылку", Toast.LENGTH_SHORT).show()
            }
        }
    }

    @JavascriptInterface
    fun appSettings() {
        activity.runOnUiThread {
            runCatching {
                activity.startActivity(
                    Intent(
                        Settings.ACTION_APPLICATION_DETAILS_SETTINGS,
                        Uri.fromParts("package", activity.packageName, null),
                    ).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
                )
            }
        }
    }

    // --- модели онлайн ------------------------------------------------------

    /**
     * Распознать картинку. Байты приходят из веба как base64 — здесь они
     * декодируются и уходят в VLM. Base64 используется только для ОДНОЙ
     * страницы по кнопке, а не для потока картинок, поэтому раздувание
     * приемлемо.
     */
    @JavascriptInterface
    fun recognizeImage(base64: String, question: String): String = online.recognize(base64, question)

    @JavascriptInterface
    fun chat(messagesJson: String, modelId: String): String = online.chat(messagesJson, modelId)

    @JavascriptInterface
    fun modelsJson(): String = online.modelsJson()

    @JavascriptInterface
    fun setApiKey(provider: String, key: String) {
        prefs.edit().putString("key.$provider", key).apply()
    }

    @JavascriptInterface
    fun hasApiKey(provider: String): Boolean =
        !prefs.getString("key.$provider", "").isNullOrBlank()

    companion object {
        fun jsonOf(items: List<Pair<String, String>>): String {
            val arr = JSONArray()
            items.forEach { (k, v) -> arr.put(JSONObject().put("k", k).put("v", v)) }
            return arr.toString()
        }

        fun decodeBase64(value: String): ByteArray? = runCatching {
            android.util.Base64.decode(value.replace(Regex("\\s"), ""), android.util.Base64.DEFAULT)
        }.getOrNull()

        fun toBase64(bytes: ByteArray): String =
            android.util.Base64.encodeToString(bytes, android.util.Base64.NO_WRAP)

        fun concatBytes(target: ByteArrayOutputStream, block: ByteArray, limit: Int) {
            if (target.size() + block.size <= limit) target.write(block)
        }
    }
}

package app.yomikai.shell.bridge

import android.content.Context
import android.util.Base64
import org.json.JSONArray
import org.json.JSONObject
import java.io.BufferedReader
import java.io.ByteArrayOutputStream
import java.net.HttpURLConnection
import java.net.URL
import java.nio.charset.StandardCharsets

/**
 * Онлайн-распознавание и чат.
 *
 * Почему это Kotlin, а не JS в веб-слое: Zen, OpenRouter и Lens не отдают
 * CORS-заголовки для браузерного origin, поэтому из страницы эти запросы
 * невозможны. Локальное распознавание (LiteRT + ML Kit, 17 МБ нативных
 * библиотек) в оболочке тоже невозможно — это ровно тот вес, которого здесь
 * нет. Остаётся мост.
 *
 * Намеренно голый: никакого OpenAI-клиента из основного приложения (там
 * 2400 строк агента с 63 инструментами), только два вызова по HTTP. Всё, что
 * нужно сверху, веб-слой собирает сам.
 */
class OnlineModels(context: Context) {

    private val prefs = context.getSharedPreferences("shell", Context.MODE_PRIVATE)

    data class Model(val id: String, val title: String, val kind: String)

    private val catalog = listOf(
        Model("google/gemini-2.5-flash", "Gemini 2.5 Flash", "vision"),
        Model("openai/gpt-4o-mini", "GPT-4o mini", "vision"),
        Model("anthropic/claude-3.5-haiku", "Claude 3.5 Haiku", "vision"),
        Model("google/gemini-2.5-flash-lite", "Gemini 2.5 Flash Lite", "text"),
    )

    fun modelsJson(): String {
        val arr = JSONArray()
        catalog.forEach {
            arr.put(
                JSONObject()
                    .put("id", it.id)
                    .put("title", it.title)
                    .put("kind", it.kind),
            )
        }
        return arr.toString()
    }

    /**
     * Распознать страницу. Возвращает JSON с текстом, иначе — объект с
     * `error`, чтобы веб показал причину, а не пустую страницу.
     */
    fun recognize(base64: String, question: String): String {
        val key = prefs.getString("key.openrouter", "") ?: return error("Нет ключа OpenRouter")
        if (base64.isEmpty()) return error("Пустая картинка")
        val bytes = runCatching { Base64.decode(base64, Base64.DEFAULT) }.getOrNull()
            ?: return error("Картинка не декодируется")
        if (bytes.size > 12 * 1024 * 1024) return error("Страница больше 12 МБ")

        val body = JSONObject()
            .put("model", prefs.getString("ocr.model", "google/gemini-2.5-flash"))
            .put(
                "messages",
                JSONArray().put(
                    JSONObject().put("role", "user").put(
                        "content",
                        JSONArray()
                            .put(
                                JSONObject().put("type", "text").put(
                                    "text",
                                    question.ifBlank { "Распознай весь текст на странице. Ответь только текстом." },
                                ),
                            )
                            .put(
                                JSONObject().put("type", "image_url").put(
                                    "image_url",
                                    JSONObject().put(
                                        "url",
                                        "data:image/png;base64,$base64",
                                    ),
                                ),
                            ),
                    ),
                ),
            )
        val response = post("https://openrouter.ai/api/v1/chat/completions", key, body.toString())
        if (response.error != null) return error(response.error)
        return JSONObject()
            .put("text", response.text)
            .put("model", response.model)
            .toString()
    }

    fun chat(messagesJson: String, modelId: String): String {
        val key = prefs.getString("key.openrouter", "") ?: return error("Нет ключа OpenRouter")
        val messages = runCatching { JSONArray(messagesJson) }.getOrNull()
            ?: return error("Не разобрались сообщения")
        val model = modelId.ifBlank { catalog.last().id }
        val body = JSONObject()
            .put("model", model)
            .put("messages", messages)
            .put("stream", false)
        val response = post("https://openrouter.ai/api/v1/chat/completions", key, body.toString())
        if (response.error != null) return error(response.error)
        return JSONObject()
            .put("text", response.text)
            .put("model", response.model)
            .toString()
    }

    private data class Reply(val text: String?, val model: String?, val error: String?)

    private fun post(url: String, key: String, payload: String): Reply {
        var connection: HttpURLConnection? = null
        return try {
            connection = (URL(url).openConnection() as HttpURLConnection).apply {
                requestMethod = "POST"
                connectTimeout = 20_000
                readTimeout = 120_000
                doOutput = true
                setRequestProperty("Authorization", "Bearer $key")
                setRequestProperty("Content-Type", "application/json")
                setRequestProperty("HTTP-Referer", "https://github.com/sj0404-collab/yomikai-shell")
            }
            connection.outputStream.use { it.write(payload.toByteArray(StandardCharsets.UTF_8)) }
            val code = connection.responseCode
            val stream = if (code in 200..299) connection.inputStream else connection.errorStream
            val text = stream?.bufferedReader()?.use(BufferedReader::readText).orEmpty()
            if (code !in 200..299) {
                Reply(null, null, "HTTP $code: ${text.take(200)}")
            } else {
                val json = runCatching { JSONObject(text) }.getOrNull()
                    ?: return Reply(null, null, "Ответ не JSON: ${text.take(120)}")
                val choice = json.optJSONArray("choices")?.optJSONObject(0)
                val content = choice?.optJSONObject("message")?.optString("content")
                    ?: return Reply(null, null, "В ответе нет текста")
                Reply(content, json.optString("model", null), null)
            }
        } catch (e: Exception) {
            Reply(null, null, e.message ?: e.javaClass.simpleName)
        } finally {
            runCatching { connection?.disconnect() }
        }
    }

    private fun error(message: String): String = JSONObject().put("error", message).toString()
}
